catalog_script_client.script:
function onLoad() {
  // Delay to wait for DOM rendering
  setTimeout(function () {
    try {
      // Only run this logic in Service Portal by checking if Angular is present
      if (typeof angular !== 'undefined' && angular.element) {
        // Hide Add button (based on sys_id)
        var addBtn = document.querySelector('#21c6ef4f1b9aee102f6dea0de54bcb9b_add_row');
        if (addBtn) addBtn.style.display = 'none';

        // Hide Remove All buttons
        var removeBtns = document.querySelectorAll('button.btn.btn-default');
        removeBtns.forEach(function (btn) {
          if (btn.innerText.trim() === 'Remove All') {
            btn.style.display = 'none';
          }
        });

        // Hide X icons (delete row)
        var deleteIcons = document.querySelectorAll('i.fa.fa-close[title="Remove Row"]');
        deleteIcons.forEach(function (icon) {
          if (icon && icon.parentElement) {
            icon.parentElement.style.display = 'none';
          }
        });
      }
    } catch (err) {
      console.error('MRVS button hide script error:', err);
    }
  }, 1500); // Allow time for rendering
}
